{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목에 맞는 개선 방법을 선택할 수 있는지 검증한다. 신고 목록 조회 쿼리의 개선 방법을 선택한 이유를 통해 원인 분석과 개선 효과 사이의 연결을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸리던 상황이다.",
          "task": "조회 지연의 원인에 맞는 쿼리 개선 방법을 선택해야 했다.",
          "action": "실행 계획에서 확인한 병목을 바탕으로 선택한 개선 방법이 해당 병목을 줄일 수 있다고 판단한 이유를 설명한다.",
          "result": "3.2초에서 0.4초로 줄어든 측정 결과를 선택의 타당성과 연결하며, 비교 조건이나 수치 해석의 한계를 설명할 수 있다."
        },
        "expectedEvidence": [
          "해당 쿼리의 개선 방법을 선택한 이유",
          "실행 계획에서 확인한 병목과 선택한 개선 방법 사이의 구체적인 연결",
          "개선 전후 측정 수치와 비교 조건이 선택의 타당성을 뒷받침하는 설명"
        ]
      },
      "question": "포켓마켓의 신고 목록 조회 쿼리를 3.2초에서 0.4초로 줄이셨네요. 해당 쿼리의 개선 방법을 선택한 이유는 무엇이었나요?",
      "answerTip": "당시 확인한 현상부터 선택 이유로 이어 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "개선 방법을 선택한 이유가 확인한 병목에 기반해 명확하게 드러난다.",
            "실행 계획에서 발견한 문제와 선택한 변경이 조회 비용을 줄이는 원리를 구체적으로 연결한다.",
            "개선 전후 수치와 비교 조건을 설명해 효과를 숫자로 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "개선 방법을 선택한 이유는 드러나지만 병목과의 연결이 일부만 설명된다.",
            "실행 계획을 확인한 사실은 제시하나 실제로 어떤 문제가 선택에 영향을 줬는지 설명이 부족하다.",
            "개선 전후 수치는 제시하지만 비교 조건이나 효과 해석이 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "선택한 이유 없이 인덱스 추가나 쿼리 수정 사실만 나열한다.",
            "확인한 병목과 개선 방법의 관계를 설명하지 못하거나 기술적으로 맞지 않게 설명한다.",
            "개선 효과를 측정한 근거 없이 빨라졌다는 인상만 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 원인을 로그로 추적하고 원인 판단의 타당성을 확인할 수 있는지 검증한다. 알림 중복 발송의 원인을 스케줄러 중복 실행으로 판단한 것이 맞는지 확인한 방법을 묻는다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어온 상황이다.",
          "task": "스케줄러 중복 실행이 실제 알림 중복 발송의 원인인지 확인해야 했다.",
          "action": "시간순으로 확인한 로그에서 두 서버의 스케줄러 실행과 알림 중복 발송을 연결한 방식 등 본인이 실제로 사용한 확인 방법을 설명한다.",
          "result": "확인한 사실이 원인 판단을 어느 정도 뒷받침했는지 설명하며, 직접 확인하지 못한 부분이 있다면 구분한다."
        },
        "expectedEvidence": [
          "스케줄러 중복 실행이 실제 원인이라는 판단을 확인한 방법",
          "두 서버의 실행 기록과 알림 중복 발송 사이의 인과관계를 뒷받침하는 로그상의 사실",
          "최초에 의심한 클라이언트 문제보다 스케줄러 중복 실행이라는 설명이 타당하다고 본 이유"
        ]
      },
      "question": "포켓마켓에서 배포 다음 날 알림 중복 발송 문의를 받으셨네요. 스케줄러 중복 실행이 원인이라는 판단이 맞았는지 무엇으로 확인하셨나요?",
      "answerTip": "처음의 추측과 직접 확인한 사실을 나눠 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "원인 판단이 맞는지 확인한 방법을 본인이 확인한 사실에 기반해 명확하게 설명한다.",
            "로그에서 확인한 두 서버의 스케줄러 실행과 알림 중복 발송의 연결을 설명해 단순한 동시 발생과 원인 관계를 구별한다.",
            "클라이언트 문제라는 최초 추측보다 스케줄러 중복 실행을 원인으로 보는 이유를 확인된 사실로 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "원인 판단의 확인 방법은 제시하지만 실제 확인 내용이 일부 불분명하다.",
            "두 서버에서 스케줄러가 실행된 로그는 설명하지만 알림 중복 발송과의 연결이 충분하지 않다.",
            "최초 추측을 바꾼 이유는 제시하나 다른 설명보다 타당하다고 본 근거가 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "원인 판단을 확인한 방법 없이 스케줄러 문제였다는 결론만 말한다.",
            "로그를 봤다는 언급만 있고 중복 실행과 중복 발송을 연결하는 사실이 없다.",
            "최초 추측을 바꾼 이유를 설명하지 못하거나 추측을 확인된 사실처럼 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "사용자 요청의 목적을 해석해 구현 범위를 구체화할 수 있는지 검증한다. 개발 담당 팀원과 범위를 조정한 경험에서 이번 구현 범위를 정한 기준 하나를 중심으로 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳의 인터뷰를 바탕으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정한 상황이다.",
          "task": "사용자 요청의 목적에 맞춰 이번에 구현할 요구사항의 경계를 정하는 것이다.",
          "action": "요청의 목적과 구현 필요성을 비교해 범위를 정한 기준을 설명하고, 실제 요구사항에 그 기준을 적용한 판단을 제시한다.",
          "result": "그 판단으로 정해진 구현 범위가 드러나며, 범위의 경계가 개발 담당 팀원과 공유할 수 있을 만큼 명확했는지 확인된다."
        },
        "expectedEvidence": [
          "이번 구현 범위를 정한 구체적인 판단 기준",
          "해당 기준을 세탁소 인터뷰에서 파악한 요청의 목적에 연결한 설명",
          "기준을 실제 요구사항에 적용해 구현 범위의 경계를 정한 사례"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨네요. 이번 구현 범위를 정한 기준은 무엇이었나요?",
      "answerTip": "실제 요청 하나에 기준을 적용한 예를 붙여 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "이번 구현 범위를 정한 기준이 구체적이며, 요구사항 사이의 선택을 설명할 수 있다.",
            "그 기준이 세탁소 인터뷰에서 확인한 요청의 목적과 어떻게 연결되는지 설명한다.",
            "실제 요구사항에 기준을 적용한 사례를 통해 구현 범위의 경계가 명확하게 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "이번 구현 범위를 정한 기준은 제시하지만 표현이 포괄적이거나 적용 방식이 불명확하다.",
            "요청의 목적과 기준의 연결을 일부 설명하지만 실제 요구사항의 범위를 가른 사례가 충분하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "이번 구현 범위를 정한 기준이 드러나지 않고 프로젝트나 문서의 구성만 소개한다.",
            "사용자 요청의 목적과 무관한 설명에 머물거나 실제 요구사항에 대한 범위 판단을 제시하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 구현 가능한 화면설계로 구체화할 수 있는지 검증한다. 화면설계서에서 예외 상황을 어느 수준까지 명시하기로 했는지, 그 상세 수준을 정한 이유를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 Figma 화면설계서 28장을 작성한 상황이다.",
          "task": "예외 상황에 대한 화면설계의 상세 수준을 정해 구현자가 동작을 임의로 해석할 여지를 줄이는 것이다.",
          "action": "실제로 다룬 예외 상황을 바탕으로 화면설계서에 명시할 수준을 정한 이유를 설명한다. 화면 상태나 안내 문구 등에 남을 수 있는 모호함과 그 판단의 관계를 제시한다.",
          "result": "선택한 상세 수준이 예외 상황의 화면 동작을 어느 정도 명확하게 했는지 설명된다. 실제 구현 완료 여부는 요구하지 않는다."
        },
        "expectedEvidence": [
          "예외 상황을 화면설계서에 어느 수준까지 구체화하기로 했는지에 대한 판단과 이유",
          "실제 예외 상황에서 화면 상태나 안내 문구의 모호함을 상세 수준 판단에 연결한 설명",
          "정한 상세 수준으로 구현자가 해석해야 할 부분이 어떻게 명확해지는지에 대한 설명"
        ]
      },
      "question": "동네 세탁소 예약 서비스의 화면설계서 28장을 작성하셨네요. 예외 상황을 화면설계서에 어느 수준까지 구체화할지 정한 이유를 들려주세요.",
      "answerTip": "예외 상황 하나를 중심으로 당시 고민을 풀어 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황을 구체화한 상세 수준과 그 수준을 선택한 이유가 명확하다.",
            "실제로 다룬 예외 상황의 화면 상태나 안내 문구를 예로 들어, 상세 수준을 정하면서 고려한 모호함을 설명한다.",
            "선택한 상세 수준이 구현자의 추측이나 추가 해석을 줄이는 이유를 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황의 상세 수준을 정한 이유는 제시하지만 어느 수준까지 명시했는지는 불명확하다.",
            "실제 화면설계의 예를 일부 제시하지만, 해당 상세 수준이 구현상의 모호함을 줄이는 이유는 충분히 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 어느 수준까지 구체화할지 정한 이유가 드러나지 않는다.",
            "화면 수나 도구 사용법, 예외 상황의 목록만 설명하고 화면설계의 상세 수준에 관한 판단을 제시하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 확인되지 않은 상태로 투약을 진행하지 않는지 검증한다. 평소의 두 배로 입력된 진통제 처방에서 투약을 멈추기로 한 판단의 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동 근무 중 수술 후 환자의 진통제 처방 용량이 평소의 두 배로 입력된 상황이다.",
          "task": "해당 처방대로 투약해도 되는지 확인되지 않은 상태에서 투약 진행 여부를 판단해야 했다.",
          "action": "처방 용량을 의심한 구체적인 이유를 설명하고, 확인 전 투약을 멈춘 판단을 환자에게 발생할 수 있는 위험과 연결한다.",
          "result": "담당의 확인으로 입력 오류가 밝혀졌다는 사실이 투약 보류 판단을 뒷받침한다."
        },
        "expectedEvidence": [
          "진통제 투약을 멈추기로 한 구체적인 판단 근거",
          "입력된 처방 용량을 그대로 수행하기 어렵다고 본 비교 정보나 환자 관련 사실",
          "담당의 확인으로 드러난 입력 오류와 투약 보류 판단의 연결"
        ]
      },
      "question": "수술 후 환자의 진통제 처방 용량이 평소의 두 배여서 투약을 멈추셨네요. 그때 투약을 멈추기로 한 판단의 근거를 들려주세요.",
      "answerTip": "당시 알았던 사실과 확인 뒤 알게 된 사실을 나눠 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
